where.if:
AND event_type = #{query.eventType}
AND CHAR_LENGTH(event_type) = CHAR_LENGTH(#{query.eventType})
AND CAST(event_type AS BINARY(64)) = CAST(#{query.eventType} AS BINARY(64))

choose.otherwise:
AND publish_status = #{query.publishStatus}
AND CHAR_LENGTH(publish_status) = CHAR_LENGTH(#{query.publishStatus})
AND CAST(publish_status AS BINARY(32)) = CAST(#{query.publishStatus} AS BINARY(32))

mapper.select:
SELECT event_no AS eventNo, event_type AS eventType, payment_order_id AS paymentOrderId, biz_no AS bizNo, event_topic AS eventTopic, downstream_system AS downstreamSystem, publish_status AS publishStatus, publish_status_type AS publishStatusType, payment_success_http_stage AS paymentSuccessHttpStage, retry_count AS retryCount, DATE_FORMAT(last_published_at, '%Y-%m-%d %H:%i:%s') AS lastPublishedAt, DATE_FORMAT(next_retry_at, '%Y-%m-%d %H:%i:%s') AS nextRetryAt, last_republish_operator AS lastRepublishOperator, DATE_FORMAT(last_republished_at, '%Y-%m-%d %H:%i:%s') AS lastRepublishedAt, event_payload AS eventPayload, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS createdAt,
FROM t_payment_event pe
LIMIT #{query.limit} OFFSET #{query.offset}
